#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int64> x(n), y(n);
    for (int i = 0; i < n; ++i) cin >> x[i] >> y[i];

    // Necessary condition:
    // For any reachable point using fixed arm lengths, parity of x+y is constant.
    int parity = ((x[0] + y[0]) & 1LL);
    for (int i = 1; i < n; ++i) {
        if (((x[i] + y[i]) & 1LL) != parity) {
            cout << -1 << '\n';
            return 0;
        }
    }

    vector<int64> d;
    // Standard construction:
    // If parity is odd: use lengths 1,2,4,...,2^31
    // If parity is even: use 1,1,2,4,...,2^31
    if (parity == 0) d.push_back(1);
    for (int i = 0; i <= 31; ++i) d.push_back(1LL << i);

    int m = (int)d.size();
    cout << m << '\n';
    for (int i = 0; i < m; ++i) {
        if (i) cout << ' ';
        cout << d[i];
    }
    cout << '\n';

    for (int i = 0; i < n; ++i) {
        int64 X = x[i], Y = y[i];
        // Transform:
        // u = x+y, v = x-y
        int64 u = X + Y;
        int64 v = X - Y;

        string ans;
        ans.reserve(m);

        // If even parity, consume the extra 1 first.
        if (parity == 0) {
            // Use one extra step to make both u,v odd afterwards.
            // Choose R for convenience: (x,y) -= (1,0)
            ans.push_back('R');
            X -= 1;
            u = X + Y;
            v = X - Y;
        }

        // Now u and v are odd, and can be represented greedily.
        // Process lengths from large to small: 2^31 ... 1
        for (int k = 31; k >= 0; --k) {
            int64 len = 1LL << k;
            // Choose signs for u and v.
            // Move so that remaining values become divisible by 2 afterwards.
            if (u >= 0 && v >= 0) {
                ans.push_back('R');
                u -= len;
                v -= len;
            } else if (u >= 0 && v < 0) {
                ans.push_back('U');
                u -= len;
                v += len;
            } else if (u < 0 && v >= 0) {
                ans.push_back('D');
                u += len;
                v -= len;
            } else {
                ans.push_back('L');
                u += len;
                v += len;
            }
        }

        if (parity == 0) {
            // Current ans is [extra step][big..small], which matches d = [1][1,2,4,...]
            // But for the powers part we appended in descending order, while d is ascending after the first.
            string out;
            out.push_back(ans[0]);
            for (int p = (int)ans.size() - 1; p >= 1; --p) out.push_back(ans[p]);
            cout << out << '\n';
        } else {
            // ans corresponds to lengths descending; reverse to match ascending d.
            reverse(ans.begin(), ans.end());
            cout << ans << '\n';
        }
    }

    return 0;
}

