        scanf("%lld %lld", &x[i], &y[i]);
    }

    // Check parity consistency
    int parity = (abs(x[0]) + abs(y[0])) % 2;
    for (int i = 1; i < n; i++) {
        if ((abs(x[i]) + abs(y[i])) % 2 != parity) {
            printf("-1\n");
            free(x);
            free(y);
            return 0;
        }
    }

    // Determine arm length
    int m;
    ll *d;

    if (parity == 0) {
        // Need an extra arm of length 1 to fix parity
        m = 32;
        d = (ll*)malloc((m + 1) * sizeof(ll));
        d[0] = 1;
        for (int i = 1; i <= m; i++) {
            d[i] = 1LL << (i - 1);
        }
        m++;
    } else {
        m = 31;
        d = (ll*)malloc(m * sizeof(ll));
        for (int i = 0; i < m; i++) {
            d[i] = 1LL << i;
        }
    }

    printf("%d\n", m);
    for (int i = 0; i < m; i++) {
        printf("%lld%c", d[i], i == m - 1 ? '\n' : ' ');
    }

    // For each target point, construct the path
    for (int i = 0; i < n; i++) {
        ll cx = 0, cy = 0;
        char *result = (char*)malloc((m + 1) * sizeof(char));
        result[m] = '\0';

        // Work backwards from largest to smallest arm
        for (int j = m - 1; j >= 0; j--) {
            ll len = d[j];

            // Try to get closer to target
            ll dx = x[i] - cx;
            ll dy = y[i] - cy;

            // Choose direction that brings us closest to target
            if (abs(dx) > abs(dy)) {
                if (dx > 0) {
                    result[j] = 'R';
                    cx += len;
                } else {
                    result[j] = 'L';
                    cx -= len;
                }
            } else {
                if (dy > 0) {
                    result[j] = 'U';
                    cy += len;
                } else {
                    result[j] = 'D';
                    cy -= len;
                }
            }
        }

        printf("%s\n", result);
        free(result);
    }

    free(x);
    free(y);
    free(d);

    return 0;
}

