public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine());
        long[] X = new long[N];
        long[] Y = new long[N];

        for (int i = 0; i < N; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            X[i] = Long.parseLong(st.nextToken());
            Y[i] = Long.parseLong(st.nextToken());
        }

        // Check parity
        int parity = (int)((Math.abs(X[0]) + Math.abs(Y[0])) % 2);
        for (int i = 1; i < N; i++) {
            if ((Math.abs(X[i]) + Math.abs(Y[i])) % 2 != parity) {
                System.out.println(-1);
                return;
            }
        }

        // Build arm lengths
        List<Long> lengths = new ArrayList<>();
        if (parity == 0) {
            lengths.add(1L);
        }

        long maxDist = 0;
        for (int i = 0; i < N; i++) {
            maxDist = Math.max(maxDist, Math.abs(X[i]) + Math.abs(Y[i]));
        }

        long power = 1;
        while (power <= maxDist) {
            lengths.add(power);
            power *= 2;
        }

        int m = lengths.size();
        System.out.println(m);

        // Output lengths
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < m; i++) {
            if (i > 0) sb.append(" ");
            sb.append(lengths.get(i));
        }
        System.out.println(sb.toString());

        // For each target point, construct the direction sequence
        for (int i = 0; i < N; i++) {
            long x = X[i];
            long y = Y[i];

            // If parity is even, we have an extra length of 1
            if (parity == 0) {
                // Try to use the extra 1 to fix parity
                // We'll handle this by adjusting the target
                // Move one step in some direction to make sum odd
                // Then the remaining sum will be even

                // We can always use the extra 1 to go up, then adjust
                // Actually, let's use a different approach
            }

            StringBuilder dirs = new StringBuilder();
            long curX = 0, curY = 0;

            for (int j = m - 1; j >= 0; j--) {
                long len = lengths.get(j);

                // Choose direction that brings us closer to target
                long bestDist = Long.MAX_VALUE;
                char bestDir = ' ';

                // Try right
                long newX = curX + len;
                long newY = curY;
                long dist = Math.abs(x - newX) + Math.abs(y - newY);
                if (dist < bestDist) {
                    bestDist = dist;
                    bestDir = 'R';
                }

                // Try left
                newX = curX - len;
                newY = curY;
                dist = Math.abs(x - newX) + Math.abs(y - newY);
                if (dist < bestDist) {
                    bestDist = dist;
                    bestDir = 'L';
                }

                // Try up
                newX = curX;
                newY = curY + len;
                dist = Math.abs(x - newX) + Math.abs(y - newY);
                if (dist < bestDist) {
                    bestDist = dist;
                    bestDir = 'U';
                }

                // Try down
                newX = curX;
                newY = curY - len;
                dist = Math.abs(x - newX) + Math.abs(y - newY);
                if (dist < bestDist) {
                    bestDist = dist;
                    bestDir = 'D';
                }

                dirs.append(bestDir);

                switch(bestDir) {
                    case 'R': curX += len; break;
                    case 'L': curX -= len; break;
                    case 'U': curY += len; break;
                    case 'D': curY -= len; break;
                }
            }

            System.out.println(dirs.toString());
        }
    }
}

