import java.io.*;
import java.util.*;

public class Main {
    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        int n = fs.nextInt();
        long[] x = new long[n];
        long[] y = new long[n];
        for (int i = 0; i < n; i++) {
            x[i] = fs.nextLong();
            y[i] = fs.nextLong();
        }

        // Necessary condition:
        // For lengths all powers of two (and optionally one extra 1),
        // all reachable points must share the same parity of x+y.
        int parity = (int) Math.floorMod(x[0] + y[0], 2);
        for (int i = 1; i < n; i++) {
            if ((int) Math.floorMod(x[i] + y[i], 2) != parity) {
                System.out.println(-1);
                return;
            }
        }

        List<Long> d = new ArrayList<>();
        for (int i = 30; i >= 0; i--) d.add(1L << i);
        boolean extraOne = false;
        if (parity == 0) {
            // Need one extra 1 to make total parity even-reachable
            d.add(1L);
            extraOne = true;
        }

        int m = d.size();
        out.append(m).append('\n');
        for (int i = 0; i < m; i++) {
            if (i > 0) out.append(' ');
            out.append(d.get(i));
        }
        out.append('\n');

        for (int i = 0; i < n; i++) {
            long tx = x[i];
            long ty = y[i];

            // Standard transform:
            // u = x + y, v = x - y
            // Choosing R/L/U/D with length l corresponds to independently
            // adding +/- l to u and +/- l to v with matched signs:
            // R: (+,+), U:(+,-), D:(-,+), L:(-,-)
            //
            // If parity is even, we appended an extra 1. Equivalently solve for
            // (x-1, y), then append 'R' for the last 1.
            StringBuilder ans = new StringBuilder();
            if (extraOne) tx--;

            long u = tx + ty;
            long v = tx - ty;

            for (int k = 0; k < 31; k++) {
                long len = 1L << (30 - k);

                // u and v always have same parity.
                // Pick signs so that after subtracting, division by 2 stays integer
                // and magnitude decreases.
                int su = ((u >= 0) ? 1 : -1);
                int sv = ((v >= 0) ? 1 : -1);

                long nu = u - su * len;
                long nv = v - sv * len;

                char c;
                if (su == 1 && sv == 1) c = 'R';
                else if (su == 1 && sv == -1) c = 'U';
                else if (su == -1 && sv == 1) c = 'D';
                else c = 'L';

                ans.append(c);
                u = nu;
                v = nv;
            }

            if (extraOne) ans.append('R');

            out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }
}
